"use client";

import React, { useRef, useMemo, useState, useEffect } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import * as THREE from "three";

// Logo wrapped as an equirectangular decal (generated from icon512ai.png).
const LOGO_EQUIRECT =
  "data:image/png;base64,";

const BRAND = "#E73A20";

/**
 * The orb: a high-segment sphere so the silhouette is a perfect circle
 * (no faceting). The brand-red body gets a subtle animated surface + fresnel
 * rim so it feels alive, and the logo is wrapped on as a decal that drifts
 * across the surface as the orb rotates.
 */
function Orb({ pointer }: { pointer: React.MutableRefObject<{ x: number; y: number }> }) {
  const group = useRef<THREE.Group>(null);
  const bodyRef = useRef<THREE.Mesh>(null);

  // Load the equirectangular logo texture (suspense-free).
  const [logoTex, setLogoTex] = useState<THREE.Texture | null>(null);
  useEffect(() => {
    new THREE.TextureLoader().load(LOGO_EQUIRECT, (t) => {
      t.colorSpace = THREE.SRGBColorSpace;
      t.anisotropy = 8;
      t.needsUpdate = true;
      setLogoTex(t);
    });
  }, []);

  // Brand body material with fresnel rim + faint animated grain.
  const bodyMat = useMemo(() => {
    const m = new THREE.MeshStandardMaterial({
      color: new THREE.Color(BRAND),
      roughness: 0.4,
      metalness: 0.12,
    });
    m.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = { value: 0 };
      (m as any).userData.shader = shader;
      shader.vertexShader = shader.vertexShader
        .replace(
          "#include <common>",
          `#include <common>
           varying vec3 vViewDirW;
           varying vec3 vNormalW;`
        )
        .replace(
          "#include <worldpos_vertex>",
          `#include <worldpos_vertex>
           vNormalW = normalize(mat3(modelMatrix) * normal);
           vViewDirW = normalize(cameraPosition - worldPosition.xyz);`
        );
      shader.fragmentShader = shader.fragmentShader
        .replace(
          "#include <common>",
          `#include <common>
           uniform float uTime;
           varying vec3 vViewDirW;
           varying vec3 vNormalW;
           float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);} `
        )
        .replace(
          "#include <dithering_fragment>",
          `#include <dithering_fragment>
           float fres = pow(1.0 - clamp(dot(normalize(vViewDirW), normalize(vNormalW)),0.0,1.0), 2.3);
           gl_FragColor.rgb += vec3(1.0,0.62,0.45) * fres * 0.5;
           gl_FragColor.rgb += (hash(gl_FragCoord.xy + uTime) - 0.5) * 0.025;`
        );
    };
    return m;
  }, []);

  const RADIUS = 1.6;

  useFrame((state, dt) => {
    const t = state.clock.elapsedTime;
    const sh = (bodyMat as any).userData.shader;
    if (sh) sh.uniforms.uTime.value = t;

    if (group.current) {
      // Slow idle spin + pointer parallax.
      const targetY = pointer.current.x * 0.6 + t * 0.15;
      const targetX = pointer.current.y * 0.35;
      group.current.rotation.y += (targetY - group.current.rotation.y) * Math.min(1, dt * 2.5);
      group.current.rotation.x += (targetX - group.current.rotation.x) * Math.min(1, dt * 2.5);
      group.current.position.y = Math.sin(t * 0.8) * 0.04;
    }
  });

  return (
    <group ref={group}>
      {/* Body: high segment count => perfectly round silhouette */}
      <mesh ref={bodyRef} material={bodyMat}>
        <sphereGeometry args={[RADIUS, 128, 128]} />
      </mesh>

      {/* Logo decal: a slightly larger sphere shell carrying the transparent logo,
          so the white glyphs sit crisply on top of the red body. */}
      {logoTex && (
        <mesh scale={1.001}>
          <sphereGeometry args={[RADIUS, 128, 128]} />
          <meshStandardMaterial
            map={logoTex}
            transparent
            roughness={0.3}
            metalness={0.05}
            depthWrite={false}
            polygonOffset
            polygonOffsetFactor={-2}
          />
        </mesh>
      )}
    </group>
  );
}

function Scene() {
  const pointer = useRef({ x: 0, y: 0 });
  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      pointer.current.x = (e.clientX / window.innerWidth - 0.5) * 2;
      pointer.current.y = (e.clientY / window.innerHeight - 0.5) * 2;
    };
    window.addEventListener("pointermove", onMove);
    return () => window.removeEventListener("pointermove", onMove);
  }, []);

  return (
    <>
      <ambientLight intensity={0.55} />
      <directionalLight position={[4, 5, 6]} intensity={2.2} />
      <directionalLight position={[-6, -2, -3]} intensity={0.6} color="#ff6a3d" />
      <Orb pointer={pointer} />
    </>
  );
}

/**
 * Drop-in orb. Transparent canvas, so it sits over your existing dark hero
 * composition. Give the wrapping element a fixed height (e.g. h-screen).
 */
export default function LogoOrb() {
  return (
    <Canvas
      dpr={[1, 2]}
      camera={{ position: [0, 0, 5], fov: 42 }}
      gl={{ antialias: true, alpha: true }}
      style={{ width: "100%", height: "100%" }}
    >
      <Scene />
    </Canvas>
  );
}
